CREATE TABLE `pokemon` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `type1` varchar(50) NOT NULL,
  `type2` varchar(50) DEFAULT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `viewed` tinyint(1) DEFAULT '0',
  `description` text,
  PRIMARY KEY (`id`)
