INSERT INTO `pokemon` VALUES (1,'Bulbasaur','grass','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/1.png',0,'A strange seed was planted on its back at birth. The plant sprouts and grows with this POKéMON.'),(2,'Ivysaur','grass','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/2.png',0,'When the bulb on its back grows large, it appears to lose the ability to stand on its hind legs.'),(3,'Venusaur','grass','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/3.png',0,'The plant blooms when it is absorbing solar energy. It stays on the move to seek sunlight.'),(4,'Charmander','fire',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/4.png',0,'Obviously prefers hot places. When it rains, steam is said to spout from the tip of its tail.'),(5,'Charmeleon','fire',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/5.png',0,'When it swings its burning tail, it elevates the temperature to unbearably high levels.'),(6,'Charizard','fire','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/6.png',0,'Spits fire that is hot enough to melt boulders. Known to cause forest fires unintentionally.'),(7,'Squirtle','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/7.png',0,'After birth, its back swells and hardens into a shell. Powerfully sprays foam from its mouth.'),(8,'Wartortle','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/8.png',0,'Often hides in water to stalk unwary prey. For swimming fast, it moves its ears to maintain balance.'),(9,'Blastoise','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/9.png',0,'A brutal POKéMON with pressurized water jets on its shell. They are used for high speed tackles.'),(10,'Caterpie','bug',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/10.png',0,'Its short feet are tipped with suction pads that enable it to tirelessly climb slopes and walls.'),(11,'Metapod','bug',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/11.png',0,'This POKéMON is vulnerable to attack while its shell is soft, exposing its weak and tender body.'),(12,'Butterfree','bug','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/12.png',0,'In battle, it flaps its wings at high speed to release highly toxic dust into the air.'),(13,'Weedle','bug','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/13.png',0,'Often found in forests, eating leaves. It has a sharp venomous stinger on its head.'),(14,'Kakuna','bug','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/14.png',0,'Almost incapable of moving, this POKéMON can only harden its shell to protect itself from predators.'),(15,'Beedrill','bug','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/15.png',0,'It has three poisonous stingers on its forelegs and its tail. They are used to jab its enemy repeatedly.'),(16,'Pidgey','normal','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/16.png',0,'A common sight in forests and woods. It flaps its wings at ground level to kick up blinding sand.'),(17,'Pidgeotto','normal','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/17.png',0,'Very protective of its sprawling territorial area, this POKéMON will fiercely peck at any intruder.'),(18,'Pidgeot','normal','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/18.png',0,'When hunting, it skims the surface of water at high speed to pick off unwary prey such as MAGIKARP.'),(19,'Rattata','normal',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/19.png',0,'Bites anything when it attacks. Small and very quick, it is a common sight in many places.'),(20,'Raticate','normal',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/20.png',0,'It uses its whis­ kers to maintain its balance. It apparently slows down if they are cut off.'),(21,'Spearow','normal','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/21.png',0,'It flaps its small wings busily to fly. Using its beak, it searches in grass for prey.'),(22,'Fearow','normal','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/22.png',0,'With its huge and magnificent wings, it can keep aloft without ever having to land for rest.'),(23,'Ekans','poison',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/23.png',0,'Moves silently and stealthily. Eats the eggs of birds, such as PIDGEY and SPEAROW, whole.'),(24,'Arbok','poison',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/24.png',0,'It is rumored that the ferocious warning markings on its belly differ from area to area.'),(25,'Pikachu','electric',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/25.png',0,'When several of these POKéMON gather, their electricity could build and cause lightning storms.'),(26,'Raichu','electric',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/26.png',0,'Its long tail serves as a ground to protect itself from its own high-voltage power.'),(27,'Sandshrew','ground',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/27.png',0,'Burrows deep underground in arid locations far from water. It only emerges to hunt for food.'),(28,'Sandslash','ground',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/28.png',0,'Curls up into a spiny ball when threatened. It can roll while curled up to attack or escape.'),(29,'Nidoran-f','poison',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/29.png',0,'Although small, its venomous barbs render this POKéMON dangerous. The female has smaller horns.'),(30,'Nidorina','poison',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/30.png',0,'The female\'s horn develops slowly. Prefers physical attacks such as clawing and biting.'),(31,'Nidoqueen','poison','ground','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/31.png',0,'Its hard scales provide strong protection. It uses its hefty bulk to execute powerful moves.'),(32,'Nidoran-m','poison',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/32.png',0,'Stiffens its ears to sense danger. The larger its horns, the more powerful its secreted venom.'),(33,'Nidorino','poison',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/33.png',0,'An aggressive POKéMON that is quick to attack. The horn on its head secretes a powerful venom.'),(34,'Nidoking','poison','ground','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/34.png',0,'It uses its powerful tail in battle to smash, constrict, then break the prey\'s bones.'),(35,'Clefairy','fairy',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/35.png',0,'Its magical and cute appeal has many admirers. It is rare and found only in certain areas.'),(36,'Clefable','fairy',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/36.png',0,'A timid fairy POKéMON that is rarely seen. It will run and hide the moment it senses people.'),(37,'Vulpix','fire',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/37.png',0,'At the time of birth, it has just one tail. The tail splits from its tip as it grows older.'),(38,'Ninetales','fire',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/38.png',0,'Very smart and very vengeful. Grabbing one of its many tails could result in a 1000-year curse.'),(39,'Jigglypuff','normal','fairy','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/39.png',0,'When its huge eyes light up, it sings a mysteriously soothing melody that lulls its enemies to sleep.'),(40,'Wigglytuff','normal','fairy','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/40.png',0,'The body is soft and rubbery. When angered, it will suck in air and inflate itself to an enormous size.'),(41,'Zubat','poison','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/41.png',0,'Forms colonies in perpetually dark places. Uses ultrasonic waves to identify and approach targets.'),(42,'Golbat','poison','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/42.png',0,'Once it strikes, it will not stop draining energy from the victim even if it gets too heavy to fly.'),(43,'Oddish','grass','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/43.png',0,'During the day, it keeps its face buried in the ground. At night, it wanders around sowing its seeds.'),(44,'Gloom','grass','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/44.png',0,'The fluid that oozes from its mouth isn\'t drool. It is a nectar that is used to attract prey.'),(45,'Vileplume','grass','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/45.png',0,'It has the world’s largest petals. With every step, the petals shake out heavy clouds of toxic pollen.'),(46,'Paras','bug','grass','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/46.png',0,'Burrows to suck tree roots. The mushrooms on its back grow by draw­ ing nutrients from the bug host.'),(47,'Parasect','bug','grass','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/47.png',0,'A host-parasite pair in which the parasite mushroom has taken over the host bug. Prefers damp places.'),(48,'Venonat','bug','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/48.png',0,'Lives in the shadows of tall trees where it eats insects. It is attracted by light at night.'),(49,'Venomoth','bug','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/49.png',0,'The dustlike scales covering its wings are color-coded to indicate the kinds of poison it has.'),(50,'Diglett','ground',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/50.png',0,'Lives about one yard underground where it feeds on plant roots. It sometimes appears above ground.'),(51,'Dugtrio','ground',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/51.png',0,'A team of DIGLETT triplets. It triggers huge earthquakes by burrowing 60 miles underground.'),(52,'Meowth','normal',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/52.png',0,'It washes its face regularly to keep the coin on its forehead spotless. It doesn’t get along with Galarian Meowth.'),(53,'Persian','normal',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/53.png',0,'Although its fur has many admirers, it is tough to raise as a pet because of its fickle meanness.'),(54,'Psyduck','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/54.png',0,'While lulling its enemies with its vacant look, this wily POKéMON will use psychokinetic powers.'),(55,'Golduck','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/55.png',0,'Often seen swim­ ming elegantly by lake shores. It is often mistaken for the Japanese monster, Kappa.'),(56,'Mankey','fighting',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/56.png',0,'Extremely quick to anger. It could be docile one moment then thrashing away the next instant.'),(57,'Primeape','fighting',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/57.png',0,'Always furious and tenacious to boot. It will not abandon chasing its quarry until it is caught.'),(58,'Growlithe','fire',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/58.png',0,'Very protective of its territory. It will bark and bite to repel intruders from its space.'),(59,'Arcanine','fire',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/59.png',0,'A POKéMON that has been admired since the past for its beauty. It runs agilely as if on wings.'),(60,'Poliwag','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/60.png',0,'Its newly grown legs prevent it from running. It appears to prefer swimming than trying to stand.'),(61,'Poliwhirl','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/61.png',0,'Capable of living in or out of water. When out of water, it sweats to keep its body slimy.'),(62,'Poliwrath','water','fighting','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/62.png',0,'An adept swimmer at both the front crawl and breast stroke. Easily overtakes the best human swimmers.'),(63,'Abra','psychic',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/63.png',0,'Using its ability to read minds, it will identify impending danger and TELEPORT to safety.'),(64,'Kadabra','psychic',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/64.png',0,'It emits special alpha waves from its body that induce headaches just by being close by.'),(65,'Alakazam','psychic',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/65.png',0,'Its brain can out­ perform a super­ computer. Its intelligence quotient is said to be 5,000.'),(66,'Machop','fighting',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/66.png',0,'Loves to build its muscles. It trains in all styles of martial arts to become even stronger.'),(67,'Machoke','fighting',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/67.png',0,'Its muscular body is so powerful, it must wear a power save belt to be able to regulate its motions.'),(68,'Machamp','fighting',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/68.png',0,'Using its heavy muscles, it throws powerful punches that can send the victim clear over the horizon.'),(69,'Bellsprout','grass','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/69.png',0,'A carnivorous POKéMON that traps and eats bugs. It uses its root feet to soak up needed moisture.'),(70,'Weepinbell','grass','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/70.png',0,'It spits out POISONPOWDER to immobilize the enemy and then finishes it with a spray of ACID.'),(71,'Victreebel','grass','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/71.png',0,'Said to live in huge colonies deep in jungles, although no one has ever returned from there.'),(72,'Tentacool','water','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/72.png',0,'Drifts in shallow seas. Anglers who hook them by accident are often punished by its stinging acid.'),(73,'Tentacruel','water','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/73.png',0,'The tentacles are normally kept short. On hunts, they are extended to ensnare and immobilize prey.'),(74,'Geodude','rock','ground','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/74.png',0,'Found in fields and mountains. Mistaking them for boulders, people often step or trip on them.'),(75,'Graveler','rock','ground','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/75.png',0,'Rolls down slopes to move. It rolls over any obstacle without slowing or changing its direction.'),(76,'Golem','rock','ground','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/76.png',0,'Its boulder-like body is extremely hard. It can easily withstand dynamite blasts without damage.'),(77,'Ponyta','fire',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/77.png',0,'Its hooves are 10 times harder than diamonds. It can trample anything completely flat in little time.'),(78,'Rapidash','fire',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/78.png',0,'Very competitive, this POKéMON will chase anything that moves fast in the hopes of racing it.'),(79,'Slowpoke','water','psychic','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/79.png',0,'Incredibly slow and dopey. It takes 5 seconds for it to feel pain when under attack.'),(80,'Slowbro','water','psychic','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/80.png',0,'The SHELLDER that is latched onto SLOWPOKE\'s tail is said to feed on the host\'s left over scraps.'),(81,'Magnemite','electric','steel','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/81.png',0,'Uses anti-gravity to stay suspended. Appears without warning and uses THUNDER WAVE and similar moves.'),(82,'Magneton','electric','steel','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/82.png',0,'Formed by several MAGNEMITEs linked together. They frequently appear when sunspots flare up.'),(83,'Farfetchd','normal','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/83.png',0,'The sprig of green onions it holds is its weapon. It is used much like a metal sword.'),(84,'Doduo','normal','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/84.png',0,'A bird that makes up for its poor flying with its fast foot speed. Leaves giant footprints.'),(85,'Dodrio','normal','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/85.png',0,'Uses its three brains to execute complex plans. While two heads sleep, one head stays awake.'),(86,'Seel','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/86.png',0,'The protruding horn on its head is very hard. It is used for bashing through thick ice.'),(87,'Dewgong','water','ice','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/87.png',0,'Stores thermal energy in its body. Swims at a steady 8 knots even in intensely cold waters.'),(88,'Grimer','poison',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/88.png',0,'Appears in filthy areas. Thrives by sucking up polluted sludge that is pumped out of factories.'),(89,'Muk','poison',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/89.png',0,'Thickly covered with a filthy, vile sludge. It is so toxic, even its footprints contain poison.'),(90,'Shellder','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/90.png',0,'Its hard shell repels any kind of attack. It is vulnerable only when its shell is open.'),(91,'Cloyster','water','ice','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/91.png',0,'When attacked, it launches its horns in quick volleys. Its innards have never been seen.'),(92,'Gastly','ghost','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/92.png',0,'Almost invisible, this gaseous POKéMON cloaks the target and puts it to sleep without notice.'),(93,'Haunter','ghost','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/93.png',0,'Because of its ability to slip through block walls, it is said to be from an­ other dimension.'),(94,'Gengar','ghost','poison','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/94.png',0,'Under a full moon, this POKéMON likes to mimic the shadows of people and laugh at their fright.'),(95,'Onix','rock','ground','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/95.png',0,'As it grows, the stone portions of its body harden to become similar to a diamond, but colored black.'),(96,'Drowzee','psychic',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/96.png',0,'Puts enemies to sleep then eats their dreams. Occasionally gets sick from eating bad dreams.'),(97,'Hypno','psychic',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/97.png',0,'When it locks eyes with an enemy, it will use a mix of PSI moves such as HYPNOSIS and CONFUSION.'),(98,'Krabby','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/98.png',0,'Its pincers are not only powerful weapons, they are used for balance when walking sideways.'),(99,'Kingler','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/99.png',0,'The large pincer has 10000 hp of crushing power. However, its huge size makes it unwieldy to use.'),(100,'Voltorb','electric',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/100.png',0,'Usually found in power plants. Easily mistaken for a POKé BALL, they have zapped many people.'),(101,'Electrode','electric',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/101.png',0,'It stores electric energy under very high pressure. It often explodes with little or no provocation.'),(102,'Exeggcute','grass','psychic','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/102.png',0,'Often mistaken for eggs. When disturbed, they quickly gather and attack in swarms.'),(103,'Exeggutor','grass','psychic','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/103.png',0,'Legend has it that on rare occasions, one of its heads will drop off and continue on as an EXEGGCUTE.'),(104,'Cubone','ground',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/104.png',0,'Because it never removes its skull helmet, no one has ever seen this POKéMON\'s real face.'),(105,'Marowak','ground',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/105.png',0,'The bone it holds is its key weapon. It throws the bone skillfully like a boomerang to KO targets.'),(106,'Hitmonlee','fighting',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/106.png',0,'When in a hurry, its legs lengthen progressively. It runs smoothly with extra long, loping strides.'),(107,'Hitmonchan','fighting',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/107.png',0,'While apparently doing nothing, it fires punches in lightning fast volleys that are impossible to see.'),(108,'Lickitung','normal',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/108.png',0,'Its tongue can be extended like a chameleon\'s. It leaves a tingling sensation when it licks enemies.'),(109,'Koffing','poison',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/109.png',0,'Because it stores several kinds of toxic gases in its body, it is prone to exploding without warning.'),(110,'Weezing','poison',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/110.png',0,'Where two kinds of poison gases meet, 2 KOFFINGs can fuse into a WEEZING over many years.'),(111,'Rhyhorn','ground','rock','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/111.png',0,'A POKéMON with a one-track mind. Once it charges,  it won\'t stop running until it falls asleep.'),(112,'Rhydon','ground','rock','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/112.png',0,'Protected by an armor-like hide, it is capable of living in molten lava of 3,600 degrees.'),(113,'Chansey','normal',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/113.png',0,'A rare and elusive POKéMON that is said to bring happiness to those who manage to get it.'),(114,'Tangela','grass',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/114.png',0,'The whole body is swathed with wide vines that are similar to sea­ weed. Its vines shake as it walks.'),(115,'Kangaskhan','normal',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/115.png',0,'The infant rarely ventures out of its mother\'s protective pouch until it is 3 years old.'),(116,'Horsea','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/116.png',0,'Known to shoot down flying bugs with precision blasts of ink from the surface of the water.'),(117,'Seadra','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/117.png',0,'Capable of swim­ ming backwards by rapidly flapping its wing-like pectoral fins and stout tail.'),(118,'Goldeen','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/118.png',0,'Its tail fin billows like an elegant ballroom dress, giving it the nickname of the Water Queen.'),(119,'Seaking','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/119.png',0,'In the autumn spawning season, they can be seen swimming powerfully up rivers and creeks.'),(120,'Staryu','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/120.png',0,'If its body is torn, it can grow back if the red core remains. The core flashes at midnight.'),(121,'Starmie','water','psychic','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/121.png',0,'Its central core glows with the seven colors of the rainbow. Some people value the core as a gem.'),(122,'Mr-mime','psychic','fairy','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/122.png',0,'If interrupted while it is miming, it will slap around the offender with its broad hands.'),(123,'Scyther','bug','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/123.png',0,'With ninja-like agility and speed, it can create the illusion that there is more than one.'),(124,'Jynx','ice','psychic','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/124.png',0,'It seductively wiggles its hips as it walks. It can cause people to dance in unison with it.'),(125,'Electabuzz','electric',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/125.png',0,'Normally found near power plants, they can wander away and cause major blackouts in cities.'),(126,'Magmar','fire',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/126.png',0,'Its body always burns with an orange glow that enables it to hide perfectly among flames.'),(127,'Pinsir','bug',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/127.png',0,'If it fails to crush the victim in its pincers, it will swing it around and toss it hard.'),(128,'Tauros','normal',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/128.png',0,'When it targets an enemy, it charges furiously while whipping its body with its long tails.'),(129,'Magikarp','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/129.png',0,'In the distant past, it was somewhat stronger than the horribly weak descendants that exist today.'),(130,'Gyarados','water','flying','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/130.png',0,'Once it begins to rampage, a GYARADOS will burn everything down, even in a harsh storm.'),(131,'Lapras','water','ice','https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/131.png',0,'A POKéMON that has been over­ hunted almost to extinction. It can ferry people across the water.'),(132,'Ditto','normal',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/132.png',0,'Capable of copying an enemy\'s genetic code to instantly transform itself into a duplicate of the enemy.'),(133,'Eevee','normal',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/133.png',0,'Its genetic code is irregular. It may mutate if it is exposed to radiation from element STONEs.'),(134,'Vaporeon','water',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/134.png',0,'Lives close to water. Its long tail is ridged with a fin which is often mistaken for a mermaid\'s.'),(135,'Jolteon','electric',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/135.png',0,'It accumulates negative ions in the atmosphere to blast out 10000- volt lightning bolts.'),(136,'Flareon','fire',NULL,'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/136.png',0,'When storing thermal energy in its body, its temperature could soar to over 1600 degrees.'),(137,'Porygon','normal',NULL,'htt